    "help.open": "打开",
    "help.faq": "常见问题",
    "help.tutorial.sale.title": "创建销售",
    "help.tutorial.sale.step1": "打开“新建销售”。",
    "help.tutorial.sale.step2": "按名称或编号查找配件。",
    "help.tutorial.sale.step3": "填写数量，选择客户和付款方式。",
    "help.tutorial.sale.step4": "确认销售后即可打开带二维码的发票，并打印或通过 WhatsApp 分享。",
    "help.tutorial.search.title": "按描述查找配件",
    "help.tutorial.search.step1": "打开“智能搜索”。",
    "help.tutorial.search.step2": "描述配件，例如 2010 年卡罗拉前刹车片。",
    "help.tutorial.search.step3": "开始搜索以查看数量、仓库和二维码。",
    "help.tutorial.search.step4": "如果没有结果，请查看产品列表或手动录入库存。",
    "help.tutorial.order.title": "向供应商订货",
    "help.tutorial.order.step1": "创建采购订单并添加配件。",
    "help.tutorial.order.step2": "以 PDF 或通过 WhatsApp 发送订单。",
    "help.tutorial.order.step3": "货物到达后创建收货单并录入额外费用。",
    "help.tutorial.order.step4": "确认收货后会计算实际成本、售价并更新库存。",
    "help.tutorial.transfer.title": "从仓库向门店调拨库存",
    "help.tutorial.transfer.step1": "打开“仓库”并创建库存调拨。",
    "help.tutorial.transfer.step2": "选择调出仓库、接收门店和数量。",
    "help.tutorial.transfer.step3": "确认调拨以更新门店库存。",
    "help.tutorial.inventory.title": "进行库存盘点",
    "help.tutorial.inventory.step1": "创建日、月、季度或年度盘点。",
    "help.tutorial.inventory.step2": "清点商品并录入实际数量。",
    "help.tutorial.inventory.step3": "确认盘点，然后查看库存报表。",
    "help.tutorial.cancel.title": "取消发票",
    "help.tutorial.cancel.step1": "打开该发票（仅限所有者）。",
    "help.tutorial.cancel.step2": "选择“取消发票”并确认。",
    "help.tutorial.cancel.step3": "二维码仍可验证，并会显示“已取消”状态。",
    "help.tutorial.company.title": "设置公司信息",
    "help.tutorial.company.step1": "打开“设置”。",
    "help.tutorial.company.step2": "填写公司名称、地址、联系方式、税费、货币和付款信息。",
    "help.tutorial.company.step3": "保存后，这些信息将显示在发票和单据上。",
    "help.tutorial.company.step4": "导出文件，以便在其他设备上复用这些设置。",
    "help.faq.invoice.question": "客户可以验证发票吗？",
    "help.faq.invoice.answer": "可以。扫描二维码即可确认发票是否真实或已取消。",
    "help.faq.stock.question": "库存不足时会怎样？",
    "help.faq.stock.answer": "库存不足时销售会被阻止。请联系库存管理员；暂未提供延迟补货申请功能。",
    "help.faq.seller.question": "如何添加销售人员？",
    "help.faq.seller.answer": "所有者在“用户”中创建账户，不允许自行注册。",
    "help.faq.session.question": "为什么我被登出了？",
    "help.faq.session.answer": "为保障安全，达到“设置”中规定的空闲时限后会自动退出。",
    "help.faq.partner.question": "如何在单据上显示合作伙伴？",
    "help.faq.partner.answer": "在“合作伙伴”中添加并启用其在发票和订单上的显示。",
