type LocaleValue = {
  language: Language;
  direction: "ltr" | "rtl";
  t: (key: string, values?: Record<string, string | number>) => string;
  changeLanguage: (language: Language) => Promise<void>;
};

const LocaleContext = createContext<LocaleValue>({
  language: "fr",
  direction: "ltr",
  t: (key, values) => interpolate(translations.fr[key] ?? key, values),
  changeLanguage: async () => {},
});

function initialLanguage(): Language {
  if (typeof window === "undefined") return "fr";
  try {
    const saved = JSON.parse(localStorage.getItem("kap-settings") ?? "{}") as {
      language?: string;
    };
    if (isLanguage(saved.language)) return saved.language;
  } catch {
    return supportedBrowserLanguage();
  }
  return supportedBrowserLanguage();
}

function supportedBrowserLanguage(): Language {
  if (typeof navigator === "undefined") return "fr";
  const short = navigator.language.toLowerCase().split("-")[0];
  return isLanguage(short) ? short : "fr";
}

function isLanguage(value: unknown): value is Language {
  return value === "fr" || value === "en" || value === "ar" || value === "zh";
}

function interpolate(value: string, values?: Record<string, string | number>) {
  return values
    ? value.replace(/\{(\w+)\}/g, (placeholder, key: string) => String(values[key] ?? placeholder))
    : value;
}

export function LocaleProvider({ children }: { children: ReactNode }) {
  const { session, refreshSession } = useAuth();
  const [language, setLanguage] = useState<Language>("fr");

  useEffect(() => {
    setLanguage(initialLanguage());
  }, []);

  useEffect(() => {
    const preferred = session?.user.preferred_language;
    if (isLanguage(preferred)) {
      setLanguage(preferred);
      saveSettings({ ...loadSettings(), language: preferred });
    }
  }, [session?.user.preferred_language]);

  useEffect(() => {
    document.documentElement.lang = language;
    document.documentElement.dir = language === "ar" ? "rtl" : "ltr";
    setFormatLocale(language);
  }, [language]);

  const changeLanguage = useCallback(
    async (next: Language) => {
      const previous = language;
      setLanguage(next);
      const settings = loadSettings();
      saveSettings({ ...settings, language: next });
      try {
        if (session) {
          await api.patch("users/me/", { preferred_language: next });
          await refreshSession();
        }
      } catch (error) {
        setLanguage(previous);
        saveSettings({ ...settings, language: previous });
        throw error;
      }
    },
    [language, refreshSession, session],
  );

  const value = useMemo<LocaleValue>(
    () => ({
      language,
      direction: language === "ar" ? "rtl" : "ltr",
      t: (key, values) =>
        interpolate(
          translations[language][key] ?? translations.en[key] ?? translations.fr[key] ?? key,
          values,
        ),
      changeLanguage,
    }),
    [changeLanguage, language],
  );

  return <LocaleContext.Provider value={value}>{children}</LocaleContext.Provider>;
}

export function useLocale() {
  return useContext(LocaleContext);
}

export function isSupportedLanguage(value: unknown): value is AppSettings["language"] {
  return isLanguage(value);
}
